pub trait InventoryGateway { async fn check_stock(&self, sku: &str)
    -> Result<Stock, GatewayError>; }                       // caller-facing contract
impl InventoryGateway for AmqpInventory {     // owns client + correlation map
    async fn check_stock(&self, sku: &str) -> Result<Stock, GatewayError> {
        let (tx, rx) = oneshot::channel();    // reply slot for this call
        self.publish(sku, self.register(tx).await).await?;
        match rx.await {                      // task suspends; thread stays free
            Ok(b) => serde_json::from_slice(&b).map_err(Into::into),
            Err(_) => Err(GatewayError::NoReply),   // sender dropped: no answer
        }
    }
}
